<?php
declare(strict_types=1); require_once __DIR__.'/../includes/functions.php'; require_auth(); $pdo=db(); if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');if($name!==''){$s=$pdo->prepare('INSERT OR IGNORE INTO categories(name,slug) VALUES(?,?)');$s->execute([$name,slugify($name)]);}redirect('/admin/categories.php');}$cats=$pdo->query('SELECT * FROM categories ORDER BY name')->fetchAll();?><!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Catégories</title><link rel="stylesheet" href="/public/css/app.css"></head><body><main class="container"><header class="section-head"><h1>Catégories</h1><a href="/admin/">← Dashboard</a></header><form class="panel" method="post"><input type="hidden" name="_csrf" value="<?=e(csrf())?>"><label>Nouvelle catégorie<input name="name" required></label><button class="btn primary">Ajouter</button></form><div class="list"><?php foreach($cats as $c):?><div class="row"><b><?=e($c['name'])?></b><small><?=e($c['slug'])?></small></div><?php endforeach;?></div></main></body></html>